#requires -Modules Pester

<#
    End-to-end + structural tests for the GitHub Actions workflow.

    Per the task requirements, the validator is NOT exercised directly here:
    every functional test case runs the real pipeline through `act` (nektos/act).
    For each case we:
      1. build a throwaway git repo containing the project files + that case's
         fixture data,
      2. run `act push --rm`, capturing stdout/stderr and the exit code,
      3. append the full output to ../act-result.txt (clearly delimited),
      4. assert act exited 0, every job reports "Job succeeded", and the parsed
         output matches the EXACT known-good values for that case's input.

    To keep `act` invocations to exactly one per case (act is slow), all cases are
    executed once in BeforeAll and the results are asserted in the It blocks.

    Structural tests (YAML shape, script references, actionlint) need no container
    and run instantly.
#>

BeforeDiscovery {
    # The functional (act) describe is skippable when docker/act are unavailable,
    # so structural tests can still run in constrained environments.
    $script:ActAvailable = [bool](Get-Command act -ErrorAction SilentlyContinue) -and
                           [bool](Get-Command docker -ErrorAction SilentlyContinue)
}

BeforeAll {
    $script:RepoRoot     = Split-Path $PSScriptRoot -Parent
    $script:WorkflowPath = Join-Path $script:RepoRoot '.github/workflows/secret-rotation-validator.yml'
    $script:ActResultLog = Join-Path $script:RepoRoot 'act-result.txt'

    # ---- Test-case catalogue: each fixture is self-contained (embeds referenceDate
    #      + warningDays) so the workflow output is fully deterministic. Expected
    #      values were computed from the validator and are asserted EXACTLY below. ----
    $script:Cases = @(
        @{
            Name     = 'mixed-urgency'
            Fixture  = @'
{
  "referenceDate": "2026-06-27",
  "warningDays": 14,
  "secrets": [
    { "name": "db-password",         "lastRotated": "2026-01-01", "rotationPolicyDays": 90,  "requiredBy": ["payments-api", "reporting-worker"] },
    { "name": "signing-key",         "lastRotated": "2025-06-01", "rotationPolicyDays": 180, "requiredBy": ["auth-service"] },
    { "name": "tls-cert",            "lastRotated": "2026-04-06", "rotationPolicyDays": 90,  "requiredBy": ["edge-gateway"] },
    { "name": "service-account-key", "lastRotated": "2026-01-01", "rotationPolicyDays": 365, "requiredBy": ["batch-pipeline"] },
    { "name": "oauth-client-secret", "lastRotated": "2026-06-20", "rotationPolicyDays": 30,  "requiredBy": ["mobile-app", "web-app"] }
  ]
}
'@
            Expected = @{
                Summary      = 'ROTATION_SUMMARY expired=2 warning=1 ok=2 total=5'
                ExpiredNames = 'EXPIRED_NAMES=signing-key,db-password'
                WarningNames = 'WARNING_NAMES=tls-cert'
            }
        },
        @{
            Name     = 'all-ok'
            Fixture  = @'
{
  "referenceDate": "2026-06-27",
  "warningDays": 14,
  "secrets": [
    { "name": "alpha", "lastRotated": "2026-06-01", "rotationPolicyDays": 365, "requiredBy": ["svc-a"] },
    { "name": "beta",  "lastRotated": "2026-05-01", "rotationPolicyDays": 200, "requiredBy": ["svc-b"] }
  ]
}
'@
            Expected = @{
                Summary      = 'ROTATION_SUMMARY expired=0 warning=0 ok=2 total=2'
                ExpiredNames = 'EXPIRED_NAMES='
                WarningNames = 'WARNING_NAMES='
            }
        },
        @{
            Name     = 'all-expired'
            Fixture  = @'
{
  "referenceDate": "2026-06-27",
  "warningDays": 14,
  "secrets": [
    { "name": "gamma",   "lastRotated": "2026-01-01", "rotationPolicyDays": 90, "requiredBy": ["svc-g"] },
    { "name": "delta",   "lastRotated": "2025-06-01", "rotationPolicyDays": 90, "requiredBy": ["svc-d"] },
    { "name": "epsilon", "lastRotated": "2026-03-01", "rotationPolicyDays": 30, "requiredBy": ["svc-e"] }
  ]
}
'@
            Expected = @{
                Summary      = 'ROTATION_SUMMARY expired=3 warning=0 ok=0 total=3'
                ExpiredNames = 'EXPIRED_NAMES=delta,epsilon,gamma'
                WarningNames = 'WARNING_NAMES='
            }
        }
    )

    # Helper: stage a throwaway git repo with the project files + a case fixture.
    function New-ActWorkspace {
        param([Parameter(Mandatory)] [string] $FixtureJson)

        $ws = Join-Path ([System.IO.Path]::GetTempPath()) ('srv-act-' + [System.Guid]::NewGuid().ToString('N'))
        New-Item -ItemType Directory -Path $ws -Force | Out-Null

        # Copy the files the workflow needs (deliberately excluding Workflow.Tests.ps1
        # so act never tries to run act-inside-act).
        New-Item -ItemType Directory -Path (Join-Path $ws '.github/workflows') -Force | Out-Null
        New-Item -ItemType Directory -Path (Join-Path $ws 'tests') -Force | Out-Null
        New-Item -ItemType Directory -Path (Join-Path $ws 'fixtures') -Force | Out-Null

